import net.minecraft.network.chat.Component; public class RealTimeEditorScreen extends ScrollableDarkScreen { private final Screen parent; private final String serverKey; private final int tabIndex; private ServerConfig sc; private TabConfig tab; private boolean dragging=false,resizing=false; private int dragOffX,dragOffY; private static final int EDGE_SNAP=10; public RealTimeEditorScreen(Screen parent,String serverKey,int tabIndex){super(Component.translatable("multichatwindows.edit_position_size"));this.parent=parent;this.serverKey=serverKey;this.tabIndex=tabIndex;} @Override protected void init(){clearWidgets();sc=ConfigManager.getOrCreateServer(serverKey);tab=(tabIndex>=0&&tabIndex<sc.tabs.size())?sc.tabs.get(tabIndex):null;int cx=width/2;addRenderableWidget(new DarkButton(cx-100,height-28,200,20,Component.translatable("multichatwindows.back"),()->{save();com.client.multichatwindows.util.MinecraftGuiAccess.setScreen(parent);}));} private void save(){if(tab==null)return;ConfigManager.saveServer(serverKey,sc);ConfigManager.saveTab(serverKey,tab);WindowService.rebuildForCurrentServer();} @Override public boolean mouseClicked(MouseButtonEvent click,boolean doubled){if(tab==null)return super.mouseClicked(click,doubled);double mx=click.x(),my=click.y();int x=tab.x,y=tab.y,w=tab.width,h=tab.height,x2=x+w,y2=y+h;boolean inside=mx>=x&&mx<=x2&&my>=y&&my<=y2;boolean corner=mx>=x2-10&&my>=y2-10;if(inside){if(corner)resizing=true;else{dragging=true;dragOffX=(int)mx-x;dragOffY=(int)my-y;}return true;}return super.mouseClicked(click,doubled);} @Override public boolean mouseReleased(MouseButtonEvent click){dragging=false;resizing=false;save();return super.mouseReleased(click);} @Override public boolean mouseDragged(MouseButtonEvent click,double offsetX,double offsetY){if(tab==null)return super.mouseDragged(click,offsetX,offsetY);double mx=click.x(),my=click.y();if(dragging){int nx=(int)mx-dragOffX,ny=(int)my-dragOffY;nx=snap(nx,0,width-tab.width);ny=snap(ny,0,height-tab.height);tab.x=nx;tab.y=ny;return true;}if(resizing){int nw=Math.max(60,(int)mx-tab.x),nh=Math.max(40,(int)my-tab.y);if(Math.abs(tab.x+nw-width)<=EDGE_SNAP)nw=width-tab.x;if(Math.abs(tab.y+nh-height)<=EDGE_SNAP)nh=height-tab.y;tab.width=nw;tab.height=nh;return true;}return super.mouseDragged(click,offsetX,offsetY);} private static int snap(int v,int min,int max){if(Math.abs(v-min)<=EDGE_SNAP)return min;if(Math.abs(v-max)<=EDGE_SNAP)return max;return v;} @Override public void extractRenderState(GuiGraphicsExtractor ctx,int mouseX,int mouseY,float delta){super.extractRenderState(ctx,mouseX,mouseY,delta);com.client.multichatwindows.util.GuiDrawHelper.centered(ctx, font,Component.translatable("multichatwindows.edit_position_size"),width/2,14,0xFFFFFFFF);if(tab!=null){int x=tab.x,y=tab.y,w=tab.width,h=tab.height,x2=x+w,y2=y+h;ctx.fill(x,y,x2,y2,0x33000000);ctx.fill(x,y,x2,y+1,0xFFFFFFFF);ctx.fill(x,y2-1,x2,y2,0xFFFFFFFF);ctx.fill(x,y,x+1,y2,0xFFFFFFFF);ctx.fill(x2-1,y,x2,y2,0xFFFFFFFF);com.client.multichatwindows.util.GuiDrawHelper.text(ctx, font,Component.translatable("multichatwindows.pos_size",x,y,w,h),20,34,0xFFFFFFFF);com.client.multichatwindows.util.GuiDrawHelper.text(ctx, font,Component.translatable("multichatwindows.drag_hint"),20,46,0xFFB0B0B0);}} }
